{
  "outcome": "escalate",
  "rationale": "We must escalate this claim because it is unclear whether the commercial use exclusion applies to the claimant's transportation of property. Under Section 6, ambiguous material facts require further investigation rather than approval or denial. This is governed by the referral of unclear coverage clause.",
  "citations": [
    {
      "clause_id": "PLUS-6.2",
      "quote": "If the documents submitted do not allow the adjuster to determine whether an exclusion applies, because material facts are disputed, missing or open to more than one reasonable reading, the claim must be escalated for further investigation rather than approved or denied on the information available."
    }
  ]
}
